fn holds_opaque_where(&self, test: &dyn Fn(&OpaqueDetail) -> bool) -> bool {
    match self {
        PropType::Opaque(detail) => test(detail),
        PropType::Union(members) | PropType::Intersection(members) | PropType::Tuple(members) => {
