import json, sys
def L(n): return json.load(open(f'/tmp/claude-501/spike/out/{n}.json'))
def diff(a, b, path=''):
    out = []
    if type(a) != type(b): return [(path, str(a)[:80], str(b)[:80])]
    if isinstance(a, dict):
        for k in set(a) | set(b):
            if k not in a or k not in b: out.append((path + '/' + k, 'missing' if k not in a else 'x', 'missing' if k not in b else 'x'))
            else: out += diff(a[k], b[k], path + '/' + k)
    elif isinstance(a, list):
        if len(a) != len(b): out.append((path, 'len%d' % len(a), 'len%d' % len(b)))
        else:
            for i, (x, y) in enumerate(zip(a, b)): out += diff(x, y, path + '[%d]' % i)
    elif a != b: out.append((path, str(a)[:80], str(b)[:80]))
    return out
for p in sys.argv[1:]:
