    for b in ['RSA', 'RSB']:
        d = diff(g, L(p + '.' + b)); print(p, 'GO vs', b, len(d), d[:6])
    try:
        d = diff(L(p + '.OFF'), g); print(p, 'OFF vs GO', len(d), d[:3])
    except FileNotFoundError: pass
